s('ctl4',"Crossing the Line","Crossing the Line: up to four lines, approved location, competent, nobody working","§3.3",{set:W=>{W.role('coss');W.pose(player,'phone');W.P.sign(5,2.4,['CROSSING','POINT'],{y:1,w:.7,h:.45,bg:'#0b4a9e',fg:'#fff'})},q:pk("How many running lines can the Crossing the Line procedure cover?",["Up to four","Two","Six","Any number"]),why:"Up to <b>four running lines</b>, at an approved location, by a competent COSS whose name is with the signallers, while <b>nobody is working</b>."});
s('ctlcall',"The crossing call","Phone the signaller: crossing location, name and employer, time needed; stay on until all across","§3.3",{set:PHONE('coss'),q:mu("What do you give the signaller for Crossing the Line?",["The crossing location","Your name and employer","How long the crossing will take","Your Sentinel number","The weather"],[0,1,2],[['Signaller','Signaller speaking.']]),why:"Give <b>location, name and employer, and the time needed</b>. When permitted, cross straight away, <b>stay on the phone</b> until everyone is in safety, then report clear."});
s('dets',"In a possession","Place detonators only after the PICOP confirms the protecting signal is at danger","§4.3",{set:W=>{W.role('coss');W.P.signal(18,2,'red');W.me(10,3)},q:pk("You've been asked to lay detonator protection for a possession. When?",["Only after the PICOP confirms the protecting signal is at danger or the route is closed","As soon as you arrive","When the last train passes","When the ES says so"]),why:"Place possession detonators <b>only after the PICOP confirms</b> the protecting signal is at danger or the route closed."});
s('wsmb',"Placing WSMBs","Place work-site marker boards only with the ES's permission","§4.3",{set:W=>{W.role('coss');W.P.wsmb(6)},q:pk("Who gives permission to place work-site marker boards?",["The ES","The PICOP","The signaller","Any COSS"]),why:"Place WSMBs in a possession <b>only with the ES's permission</b>."});
s('visitor',"Visitor on site","Visitors with a permit: brief them, sign and keep the permit, stay with them","§8",{set:W=>{W.role('coss');W.guy({x:2,z:3,vest:0xf5e042,helmet:0xffffff,tag:'VISITOR',face:Math.PI/2})},q:pk("A visitor with an approved permit joins your site.",["Brief them, sign and keep the permit, and stay with them until they leave the railway","Let them walk around","Hand them to the lookout","They don't need a briefing"]),why:"<b>Brief</b> the visitor, <b>sign and keep</b> the permit, and <b>stay with them</b> until they leave the operational railway."});
