s('dark',"Night patrol","No patrolling alone in darkness, poor visibility or a tunnel","§3.2",{set:W=>{W.night(true);R(W)},q:pk("It's dark. Can you patrol alone this way?",["No: not in darkness, poor visibility or a tunnel","Yes, with a lamp","Yes, looking up every 3 seconds","Yes, on a slow line"]),why:"<b>Not in darkness, poor visibility or a tunnel.</b>"});
s('rigid',"Behind a fence","Rigid/tensioned barrier or permanent fence at 1.25 m: work on the safe side","§3.3",{set:W=>{R(W);W.P.barrier('rigid',-6,10,R1+1.25);W.me(1,3.4)},q:pk("A rigid barrier stands 1.25 m from the rail. Can you work behind it?",["Yes, on the safe side","Only below 40 mph","Only with ATWS","No"]),why:"Rigid, tensioned or permanent fence at <b>1.25 m or more</b>: work on the safe side."});
s('tape',"Tape at 1.25 m","Tape/netting at 1.25 m only up to 40 mph; at 2 m any speed","§3.3",{set:W=>{R(W);W.speed(75);W.P.barrier('tape',-6,10,R1+1.25)},q:pk("Barricade tape at 1.25 m on a 75 mph line.",["Not allowed: tape at 1.25 m only up to 40 mph (at 2 m, any speed)","Fine","Fine with ATWS","Fine in daylight"]),why:"Tape or netting at 1.25 m: <b>40 mph or less</b>. At <b>2 m</b> there's no speed limit."});
s('09',"0.9 m barrier","Never use a 0.9 m barrier, even with ATWS","§3.3",{set:W=>{R(W);W.P.barrier('rigid',-6,10,R1+.9)},q:pk("There's a barrier at 0.9 m, with ATWS. Part of your safe system?",["No, never, even with ATWS","Yes","Yes below 40 mph","Yes with a second warning"]),why:"A barrier at <b>0.9 m</b> must not be part of your safe system, <b>even with ATWS</b>."});
