s('calc',"Your warning time","Add 5 s for working alone, 10 s minimum in safety; total 45 s or less","Aid",{set:W=>{R(W);W.card('<div class="form"><b>Warning time</b><span>Stop & down tools: 5 s<br>Working alone: ?<br>Walk to safety: 10 s<br>Minimum in safety: ?</span></div>')},q:pk("Stop 5 s, walk 10 s. Add what's needed for working alone and time in safety. Total?",["30 seconds","20 seconds","25 seconds","15 seconds"]),why:"5 (stop) + <b>5 (alone)</b> + 10 (walk) + <b>10 (in safety)</b> = <b>30 s</b>. It must be 45 s or less."});
