s('arm',"Lookout armlet","Lookout: white armlet with LOOKOUT in red","§2",{set:W=>{W.role('lo');W.me(0,3,0)},q:pk("What does the lookout armlet look like?",["White with LOOKOUT in red letters","Blue with white letters","Yellow with blue letters","White with blue letters"]),why:"<b>White, with LOOKOUT in red</b>, left arm or upper chest."});
