s('cert',"Can you be lookout?","Carry a valid lookout certificate","§1",{set:W=>{W.role('lo');W.card('<div class="idc"><b>SENTINEL</b><span>PTS · Lookout</span></div>')},q:pk("What do you need to act as a lookout or site warden?",["A valid lookout certificate of competence","Just PTS","A COSS ticket","Five years' experience"]),why:"A valid <b>lookout certificate of competence</b>."});
