s('chat',"Fancy a chat?","Don't allow yourself to be distracted","§4",{set:W=>{L(W);const m=W.guy({x:1.4,z:3.2,face:-Math.PI/2});W.say(m,'Did you watch the match?',4000)},q:pk("A mate wanders over to chat about the football.",["Don't get drawn in: you must not be distracted","Chat but keep looking","Chat between trains","Ask him to stand where you can see the line"]),why:"<b>Don't allow yourself to be distracted.</b>"});
