s('getback',"Over the line","Site warden: shout \"get back\", then short sharp blasts until they return","§3",{set:W=>{W.role('sw');W.P.barrier('tape',-6,10,R1+2.05);W.me(-3,3.9,-Math.PI/2);const m=W.guy({x:2,z:2.2,face:Math.PI});},q:pk("Someone steps over the limit of the safe area.",["Shout \"get back\"; if they don't come straight back, short sharp blasts until they do","Tell the COSS at break","Pull them back","Stop all work and ring the signaller"]),why:"Shout <b>\"get back\"</b>. If they don't return at once, give <b>repeated short sharp blasts</b> until they do."});
